query ListTodos($limit: Int = 20, $offset: Int = 0, $status: String) {
  nodes(
    filter: { tableId: "58", attributeFilter: { name: "status", value: $status } }
    pagination: { limit: $limit, offset: $offset }
  ) {
    nodes {
      id
      content
      createdAt
      attributes {
        name
        value
      }
    }
    totalCount
    hasNextPage
  }
}
